"""Data continuation, executed by build_fragment.py in its helper namespace."""
OP='Operator algebras and index theory'
talk(306,'1973-09-24','A. A. Kirillov','P000511-P000513','Brown--Douglas--Fillmore extensions and analytic K-homology',r'The explicit Kirillov heading is on the lower part of P000512; the discussion ends before the Fuchs heading on P000513. It presents extensions by compact operators, their Calkin-algebra description, the emerging homology theory and index pairings, and applications to normal operators. The catalogue lists this record before Gelfand, but the notebook order is the reverse. \citet[pp.~699--702]{douglas1980extensions} retrospectively identifies which results were in the April 1973 Halifax paper and which received fuller treatment in 1977. A garbled degree formula and the unspecified affine-group example are not silently completed.')
item(306,'P000512','definition','C*-extensions by the compact operators',r'\(0\to\mathcal K\to\mathcal A\to C(X)\to0\), called an extension of Banach algebras; \(X\) is compact and \(\mathcal K\) acts on a separable Hilbert space.',r'For nonempty compact metrizable \(X\) and an infinite-dimensional separable complex Hilbert space \(H\), consider essential C*-algebra extensions of \(C(X)\) by \(\mathcal K(H)\), with *-homomorphisms and the usual equivalence modulo addition of split extensions. In this category the resulting \(\operatorname{Ext}(X)\) is an abelian group.',r'\citet{browndouglasfillmore1973unitary}; the definitions and chronology are checked in the authors\textquoteright s retrospective \citet[pp.~699--701]{douglas1980extensions}.',[BDF,D78],literal='correct with missing hypotheses',reconstruction=r'C*-structure, metrizability, essentiality and stable equivalence replace the misleading unrestricted Banach-algebra wording.',subject=OP)
item(306,'P000512','construction','Busby maps, splitting and addition',r'Embeddings \(C(X)\hookrightarrow\mathcal L/\mathcal K\) are taken up to unitary equivalence; those lifting to \(\mathcal L\) are trivial. Addition is \(\tau_1\oplus\tau_2\) on \(H_1\oplus H_2\cong H\).',r'An essential extension determines an injective *-homomorphism \(\tau:C(X)\to\mathcal Q(H)=\mathcal B(H)/\mathcal K(H)\), and its pullback recovers the extension. A *-homomorphic lift defines a split class. Direct sum, followed by a unitary identification of infinite-dimensional separable Hilbert spaces, gives the addition on Ext; stable equivalence makes the choice immaterial.',r'\citet[p.~700]{douglas1980extensions} gives precisely these equivalent constructions and attributes the commutative case to the 1973 work.',[D78,BDF],literal='correct with missing hypotheses',subject=OP)
item(306,'P000512','theorem','Suspensions and the homological interpretation',r'\(\operatorname{Ext}_{1-n}(X)=\operatorname{Ext}(S^nX)\); the main result is said to reduce Atiyah\textquoteright s \(\operatorname{Ell}(X)\) to Ext.',r'For based finite CW complexes, reduced groups \(\widetilde E_{1-n}(X)=\operatorname{Ext}(\Sigma^nX)\) extend, with periodicity, to reduced complex K-homology. In particular \(\operatorname{Ext}(X)\cong K_1(X)\), whereas even Fredholm cycles represent \(K_0(X)\). The relation with Atiyah\textquoteright s Ell uses the even group and an equivalence relation on cycles; it is not literally \(\operatorname{Ell}(X)=\operatorname{Ext}_1(X)\).',r'\citet[p.~702]{douglas1980extensions} distinguishes the two degrees and the solution of Atiyah\textquoteright s problem; the full treatment is \citet{browndouglasfillmore1977extensions}.',[D78,'browndouglasfillmore1977extensions'],literal='correct with missing hypotheses',reconstruction=r'Reduced suspensions, the even/odd degree distinction, and the cycle quotient are supplied. The result was announced in the BDF programme before this exposition; the 1977 proof date is not its first circulation.',subject=OP)
item(306,'P000513','theorem','Exact sequence for a closed subcomplex',r'The sequence begins \(\operatorname{Ext}_1(A)\to\operatorname{Ext}_1(X)\to\operatorname{Ext}_1(X/A)\to\operatorname{Ext}_0(A)\).',r'For a based finite CW pair \((X,A)\) with \(A\ne\varnothing\) a subcomplex, the reduced BDF homology groups have the cofiber long exact sequence \(\cdots\to\widetilde E_1(A)\to\widetilde E_1(X)\to\widetilde E_1(X/A)\to\widetilde E_0(A)\to\cdots\).',r'The generalized homology theorem in \citet[p.~702]{douglas1980extensions} supplies the exactness framework; \citet{browndouglasfillmore1977extensions} is the full original treatment.',[D78,'browndouglasfillmore1977extensions'],literal='correct with missing hypotheses',reconstruction=r'The finite CW-pair scope avoids treating an arbitrary inclusion as a cofiber sequence without qualifications.',subject=OP)
item(306,'P000513','construction','The family index pairing',r'\(K^1(X\times Y)\times\operatorname{Ext}_1(X)\to K^0(Y)\).',r'For finite CW complexes \(X,Y\), an odd K-cohomology class over \(X\times Y\) and an extension class in \(K_1(X)\) give a class in \(K^0(Y)\): apply the Busby map to a matrix representative, lift to a continuous Fredholm family, and take its index bundle. For \(Y=\mathrm{pt}\) this is the integer Fredholm-index pairing.',r'The scalar pairing and the K-homology identification are checked in \citet[pp.~702--703]{douglas1980extensions}; the family refinement is a reconstruction of the explicit notebook formula, not a separately located theorem in the accessible 1973 text.',[D78,BDF],literal='correct with missing hypotheses',match='partial',verification='indirect',reconstruction=r'Finite complexes, stabilized representatives and norm-continuous local lifts are needed for the family index; the compressed first line in the notebook does not fix degrees.',subject=OP)
item(306,'P000513','claim','The garbled relation between Ext and degree-zero K-homology',r'The boxed formula is transcribed \(\operatorname{Ext}_1\oplus\mathbb Z=K_0\) for simplicial complexes; the operation is overwritten, but the subscript 1 is visible in the scan.',r'With the suspension convention on P000512, for a connected based finite CW complex \(X\) the correct degree-zero formula is \(\operatorname{Ext}(\Sigma X)\oplus\mathbb Z\cong K_0(X)\). It cannot be \(\operatorname{Ext}(X)\oplus\mathbb Z\): at \(X=S^1\) that would incorrectly identify \(\mathbb Z^2\) with \(\mathbb Z\).',r'\citet[p.~702]{douglas1980extensions} explicitly identifies \(E_0(X)\) with \(K_0(X)\).',[D78],literal='false as written',match='partial',reconstruction=r'This is a degree correction, not a proposed decipherment of the overwritten operation. The added summand is the unreduced basepoint summand.',development='annotated',subject=OP)
item(306,'P000513','question','The affine-group extension and two indices',r'\(0\to\mathcal K\to C^*(ax+b)\to C(\infty)\to0\), \(\operatorname{Ext}(\infty)=\mathbb Z+\mathbb Z\); the notes ask for the pair for a specific operator.',r'If the infinity-shaped symbol denotes the figure-eight graph \(S^1\vee S^1\), its Ext group is \(\mathbb Z^2\), with two index coordinates. But the group version of \(ax+b\), its representation, the precise ideal and the operator whose indices are requested are not recorded, so no numerical pair is determined.',r'The planar index classification in \citet[pp.~701--702]{douglas1980extensions} explains the graph interpretation. It does not identify this particular affine-group extension. The scan confirms an infinity-shaped symbol, not a written definition of the space.',[D78],cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',reconstruction=r'The figure-eight interpretation is conditional. It is not substituted for the source symbol as an established transcription correction.',status='the numerical question is underdetermined; no problem-index entry or claim of a remaining research problem is justified.',subject=OP)
item(306,'P000513','theorem','Extensions of the circle are classified by the index',r'For \(X=\mathbb T\), the image \(T\) of the generator satisfies \(TT^*=1\bmod\mathcal K\); the answer is the index.',r'A unital Busby map \(C(S^1)\to\mathcal Q(H)\) sends the coordinate function to a unitary in the Calkin algebra. Every lift \(T\) satisfies both \(TT^*-1\in\mathcal K\) and \(T^*T-1\in\mathcal K\), is Fredholm, and determines the extension by its index. Thus \(\operatorname{Ext}(S^1)\cong\mathbb Z\), with sign depending on the choice of generator.',r'\citet[pp.~701--702]{douglas1980extensions}; compare the equivalent normal-operator classification in \citet[Theorem~1.1 and following paragraph]{friisrordam2001approximation}.',[D78,FR],literal='correct with missing hypotheses',reconstruction=r'The missing second unitary relation follows from the *-homomorphism. The single displayed relation alone would allow a coisometry with infinite-dimensional kernel, which is not Fredholm.',subject=OP)
item(306,'P000513','theorem','Normal operators plus compact operators form a closed set',r'\(\{N+K:N\text{ normal},K\text{ compact}\}\) is norm closed.',r'On an infinite-dimensional separable complex Hilbert space, the set of compact perturbations of bounded normal operators is closed in operator norm. Equivalently, an essentially normal operator belongs to it exactly when \(\operatorname{ind}(T-\lambda)=0\) for every \(\lambda\notin\sigma_{\rm ess}(T)\).',r'The 1973 BDF result is reproved in \citet[Theorem~1.1 and \S2, proof of Theorem~1.1]{friisrordam2001approximation}; the primary article identifies BDF Corollary~11.2 as the original source.',[BDF,FR],subject=OP)
item(306,'P000513','claim','The asserted failure of closure for pairs',r'The circled insertion says that pairs \((N_1+K_1,N_2+K_2)\), with commuting normal \(N_1,N_2\), are not closed among pairs of this kind.',r'One possible reading is nonclosure in \(\mathcal B(H)^2\) of compact perturbations of commuting bounded normal pairs. The notebook gives no example and its phrase ``all pairs of this kind'' leaves the ambient class unclear. This is kept separate from the verified one-operator theorem.',r'Exact-phrase and BDF-title searches, the available 1973 metadata, \citet[pp.~699--704]{douglas1980extensions}, and \citet[\S2]{friisrordam2001approximation} did not locate the asserted pair counterexample. Neither the one-variable theorem nor general Ext theory alone verifies it.',[D78,FR,BDF],cls='F',literal='not determinable',match='none found',verification='unresolved lead',confidence='low',status='a recorded claim whose precise ambient hypotheses and primary counterexample remain unresolved in this audit; it is not classified as an unsolved research problem.',subject=OP)
